function origin(){return(process.env.ALPHALAB_API_ORIGIN||'http://127.0.0.1:8000').replace(/\/+$/,'')}
async function get(path){const r=await fetch(origin()+path,{headers:{Accept:'application/json'}});if(!r.ok)throw new Error('AlphaLab API '+r.status+': '+await r.text());return r.json()}
function delay(ms){return new Promise(resolve=>setTimeout(resolve,ms))}
async function run(input){if(input.confirm_python_execution!==true)throw new Error('Backtest requires an explicit user request and confirm_python_execution=true');const id=String(input.project_id||'').trim();if(!id)throw new Error('project_id is required');const project=await get('/api/pipeline/projects/'+encodeURIComponent(id));if(!project.source_sha256||!Array.isArray(project.component_manifest)||project.component_manifest.length!==3)throw new Error('Pipeline project is incomplete');const response=await fetch(origin()+'/api/backtests/jobs',{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json'},body:JSON.stringify({project_id:id,start_date:String(input.start_date||'').trim(),end_date:String(input.end_date||'').trim(),profile:input.profile==='runtime'?'runtime':'demo'})});if(!response.ok)throw new Error('AlphaLab API '+response.status+': '+await response.text());let job=await response.json();const deadline=Date.now()+840000;while(job.status==='queued'||job.status==='running'){if(Date.now()>=deadline)throw new Error('Backtest job '+job.id+' is still running; query it again from the Backtest workbench');await delay(2000);job=await get('/api/backtests/jobs/'+encodeURIComponent(job.id))}if(job.status!=='succeeded'||!job.result)throw new Error(job.error||job.message||'Backtest job failed');const result=job.result;if(result.source_sha256!==project.source_sha256||result.provenance?.strategy_python_sha256!==project.source_sha256)throw new Error('Pipeline source changed during backtest');if(result.provenance?.strategy_python?.source)result.provenance.strategy_python={sha256:result.provenance.strategy_python.sha256};return{...result,job_id:job.id,project_preflight:{project_id:id,revision:project.revision,source_sha256:project.source_sha256,component_manifest:project.component_manifest}}}
